async function loadScoutMap(){if(!document.querySelector('link[data-scout-leaflet]')){const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';css.dataset.scoutLeaflet='1';document.head.append(css)}if(!window.L)await new Promise((resolve,reject)=>{const existing=document.querySelector('script[data-scout-leaflet]');if(existing){existing.addEventListener('load',resolve,{once:true});existing.addEventListener('error',reject,{once:true});return}const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';script.dataset.scoutLeaflet='1';script.onload=resolve;script.onerror=reject;document.head.append(script)});const mapEl=$('#scoutMap');if(!mapEl||scout.map)return;const center=scoutAreas[scout.area].center;scout.map=window.L.map(mapEl,{zoomControl:false}).setView(center.slice(0,2),center[2]);window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(scout.map);window.L.control.zoom({position:'bottomright'}).addTo(scout.map);scout.pins=window.L.layerGroup().addTo(scout.map);scout.outline=window.L.layerGroup().addTo(scout.map);scout.ready=true;setTimeout(()=>scout.map.invalidateSize(),50)}
function drawScoutPins(){if(!scout.pins)return;scout.pins.clearLayers();const bounds=[];for(const feature of scout.features){const g=feature.geometry;if(!g||!Number.isFinite(g.x)||!Number.isFinite(g.y))continue;const point=[g.y,g.x],marker=window.L.circleMarker(point,{radius:7,color:'#fff',weight:2,fillColor:'#1f6b5c',fillOpacity:.95}).addTo(scout.pins);marker.bindTooltip(feature.attributes?.FullAddr||`${feature.attributes?.COUNTY_NAME||'Walton'} County property`);marker.on('click',()=>selectScoutProperty(scoutParcel(feature)));bounds.push(point)}if(scout.query&&bounds.length)scout.map.fitBounds(bounds,{maxZoom:17,padding:[35,35]})}
function scoutLeadIds(){return new Set((state.data.contacts||[]).filter(c=>(c.tags||[]).includes('Property Scout')).map(c=>String(c.notes||'').match(/^Parcel:\s*(.+)$/m)?.[1]).filter(Boolean))}
const scoutText=value=>String(value??'').trim(),scoutAddressKey=value=>scoutText(value).toUpperCase().replace(/\b(ROAD|RD|STREET|ST|AVENUE|AVE|DRIVE|DR|LANE|LN|COURT|CT|BOULEVARD|BLVD)\b/g,'').replace(/[^A-Z0-9]/g,'');
function scoutDate(value){if(!value)return'';const text=String(value).trim(),raw=Number(value),local=text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/),iso=text.match(/^(\d{4})-(\d{2})-(\d{2})$/);let date;if(local)date=new Date(Number(local[3]),Number(local[1])-1,Number(local[2]),12);else if(iso)date=new Date(Number(iso[1]),Number(iso[2])-1,Number(iso[3]),12);else if(Number.isFinite(raw)&&raw>1e11){const utc=new Date(raw);date=new Date(utc.getUTCFullYear(),utc.getUTCMonth(),utc.getUTCDate(),12)}else if(/^\d{8}$/.test(text))date=new Date(`${text.slice(0,4)}-${text.slice(4,6)}-${text.slice(6,8)}T12:00:00`);else if(Number.isFinite(raw)&&raw>19000101){const numeric=String(Math.trunc(raw));date=new Date(`${numeric.slice(0,4)}-${numeric.slice(4,6)}-${numeric.slice(6,8)}T12:00:00`)}else date=new Date(value);return Number.isNaN(date.getTime())?'':date.toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'})}
function scoutExistingContact(feature){const parcel=scoutParcel(feature);return (state.data.contacts||[]).find(c=>String(c.notes||'').match(/^Parcel:\s*(.+)$/m)?.[1]===parcel)}
function scoutSignals(feature){const a=feature.attributes||{},site=scoutAddressKey(a.FullAddr),mail=scoutAddressKey([a.OWN_ADDRESS_1,a.OWN_ADDRESS_2].filter(Boolean).join(' ')),occupied=site&&mail?site.includes(mail)||mail.includes(site):null,lastSale=scoutDate(a.SALE_DATE_1),years=lastSale?Math.max(0,Math.floor((Date.now()-new Date(lastSale).getTime())/31557600000)):null,holdings=Number(feature.ownerHoldings||0);return {occupied,lastSale,years,holdings}}
