views.documents=async()=>{const docs=await api('/documents');$('#app').innerHTML=header('DOCUMENT CENTER','Documents','Files that are not yet assigned to a contact, listing, transaction, or task.',`<button class="btn primary" id="addGeneralDocument">＋ Upload document</button>`)+`<section class="card"><div class="card-head"><h2>General documents</h2>${badge(docs.length,'gray')}</div><div class="document-list" style="padding:14px 26px">${docs.length?docs.map(d=>documentRow(d,'general')).join(''):empty('No general documents','Upload a file here when it does not belong to a specific CRM record yet.')}</div></section>`;$('#addGeneralDocument').onclick=()=>openDocumentManager('general',null,'General documents');bindManagedDocumentActions(()=>go('documents'))};
const calendarKey=value=>String(value||'').slice(0,10);
function taskListingAddress(task){return task.listing_address||(state.data.listings||[]).find(listing=>listing.id===Number(task.listing_id))?.address||''}
function calendarItems(){const items=[];for(const task of state.data.tasks||[])if(!task._calendar&&task.status!=='completed'&&task.due_at){const address=taskListingAddress(task),startTime=String(task.due_at).slice(11,16),endTime=task.end_at?String(task.end_at).slice(11,16):'';items.push({date:calendarKey(task.due_at),time:[startTime,endTime].filter(Boolean).join('–'),title:`${task.title}${address?` — ${address}`:''}`,detail:[task.contact_name,address].filter(Boolean).join(' · ')||'Task',kind:'task',id:task.id,status:task.status})}for(const contact of state.data.contacts||[]){const name=`${contact.first_name} ${contact.last_name}`.trim();if(contact.next_follow_up)items.push({date:calendarKey(contact.next_follow_up),title:`Follow-up — ${name}`,detail:'Contact follow-up',kind:'followup',id:contact.id});if(contact.last_contact)items.push({date:calendarKey(contact.last_contact),title:`Last contact — ${name}`,detail:'Contact history',kind:'contact',id:contact.id})}const fields=[['contract_date','Contract date'],['inspection_date','Inspection'],['appraisal_date','Appraisal'],['financing_deadline','Financing deadline'],['final_walkthrough_date','Final Walk Through'],['closing_date','Closing']];for(const transaction of state.data.transactions||[])if(transaction.status!=='Cancelled')for(const [field,label] of fields)if(transaction[field])items.push({date:calendarKey(transaction[field]),time:String(transaction[field]).slice(11,16),title:`${label} — ${transaction.property}`,detail:transaction.buyer_name||transaction.seller_name||'Transaction',kind:'transaction',id:transaction.id});return items.filter(x=>x.date).sort((a,b)=>`${a.date}${a.time||''}`.localeCompare(`${b.date}${b.time||''}`))}
function calendarEntry(item){return `<button class="calendar-event ${item.kind}" data-calendar-kind="${item.kind}" data-calendar-id="${item.id}" title="${esc(item.title)}">${item.time?`<span>${esc(item.time)}</span>`:''}${esc(item.title)}</button>`}
async function completeFollowUp(contactId,returnView=state.view){const contact=(state.data.contacts||[]).find(x=>x.id===Number(contactId));if(!contact)return toast('Contact not found',true);const completedAt=new Date().toISOString();await api('/activities',{method:'POST',body:JSON.stringify({contact_id:contact.id,type:'Follow-up',direction:'Outgoing',subject:'Completed follow-up',body:`Completed the follow-up scheduled for ${fmtDate(contact.next_follow_up)}.`,occurred_at:completedAt})});await api('/contacts/'+contact.id,{method:'PUT',body:JSON.stringify({next_follow_up:null,last_contact:completedAt})});toast(`Follow-up with ${contact.first_name} completed`);if(returnView==='contact')showContact(contact.id);else go(returnView)}
