function assistantMessage(role,content,action='',index=-1,rating=''){const feedback=role==='assistant'&&index>=0?`<div class="assistant-feedback" aria-label="Rate this recommendation"><span>${rating==='helpful'?'Saved as helpful.':rating==='correction'?'Correction saved.':'Was this useful?'}</span>${rating?'':`<button type="button" data-assistant-feedback="helpful" data-message-index="${index}">Yes</button><button type="button" data-assistant-feedback="correction" data-message-index="${index}">Needs correction</button>`}</div>`:'';return `<article class="assistant-message ${role}"><div class="assistant-avatar">${role==='user'?'EH':'✦'}</div><div class="assistant-bubble">${role==='user'?`<p>${esc(content)}</p>`:content}${action?`<div class="assistant-actions">${action}</div>`:''}${feedback}</div></article>`}
