function startAssistantVoice(){const input=$('#assistantInput'),button=$('#assistantVoice'),SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!input||!button)return;if(assistantRecognition){assistantRecognition.stop();assistantRecognition=null;assistantVoiceStatus('Voice input stopped. Review the text, then tap Ask.');return}if(!SpeechRecognition){input.focus();assistantVoiceStatus('Use the microphone on the iPhone keyboard, then tap Ask.');toast('The iPhone keyboard microphone is ready to use.');return}try{const recognition=new SpeechRecognition();assistantRecognition=recognition;recognition.lang='en-US';recognition.interimResults=true;recognition.continuous=false;recognition.maxAlternatives=1;let finalText='',startingText=input.value.trim();button.classList.add('listening');button.setAttribute('aria-pressed','true');assistantVoiceStatus('Listening… Speak now. Tap the microphone again to stop.');recognition.onresult=event=>{let interim='';for(let index=event.resultIndex;index<event.results.length;index++){const words=event.results[index][0]?.transcript||'';if(event.results[index].isFinal)finalText+=words;else interim+=words}const spoken=(finalText||interim).trim();input.value=[startingText,spoken].filter(Boolean).join(startingText&&spoken?' ':'');input.dispatchEvent(new Event('input',{bubbles:true}));assistantVoiceStatus(finalText?'Voice text added. Review it, then tap Ask.':'Listening… '+interim)};recognition.onerror=event=>{const messages={'not-allowed':'Microphone access is off. In iPhone Settings, allow microphone access for Safari, then try again.','audio-capture':'No microphone was available. Check the iPhone microphone permission and try again.',network:'Voice transcription could not connect. Check your internet connection, or use the iPhone keyboard microphone.','no-speech':'I did not hear anything. Tap the microphone and try again.',aborted:'Voice input stopped.'};assistantVoiceStatus(messages[event.error]||'Voice input could not start. Use the iPhone keyboard microphone instead.',event.error!=='aborted')};recognition.onend=()=>{assistantRecognition=null;button?.classList.remove('listening');button?.setAttribute('aria-pressed','false');if(finalText)assistantVoiceStatus('Voice text added. Review it, then tap Ask.')};recognition.start()}catch(error){assistantRecognition=null;button.classList.remove('listening');input.focus();assistantVoiceStatus('Use the microphone on the iPhone keyboard, then tap Ask.',true)}}
