async function previewListingCsv(event){const file=event.target.files?.[0];if(!file)return;const rows=parseCsv(await file.text());const preview=$('#listingCsvPreview');if(rows.length<2){preview.innerHTML='<div class="csv-error">No listing rows were found in that CSV.</div>';return}const headers=rows[0].map(x=>x.replace(/^\uFEFF/,'')),items=rows.slice(1).map(values=>listingFromCsv(headers,values)).filter(item=>item.address);if(!items.length){preview.innerHTML='<div class="csv-error">I could not find a property address column. Try the template or export a report that includes the full address.</div>';return}const prepared=items.map(item=>({item,existing:matchImportedListing(item)}));const updates=prepared.filter(x=>x.existing).length;preview.innerHTML=`<div class="csv-summary"><strong>${prepared.length}</strong> listing${prepared.length===1?'':'s'} ready · ${prepared.length-updates} new · ${updates} update${updates===1?'':'s'}</div><div class="table-wrap csv-preview-table"><table><thead><tr><th>Action</th><th>Property</th><th>MLS</th><th>Price</th><th>Details</th></tr></thead><tbody>${prepared.map(({item,existing})=>`<tr><td>${badge(existing?'Update':'Add',existing?'gold':'gray')}</td><td><b>${esc(item.address)}</b></td><td>${esc(item.mls||'—')}</td><td>${fmtMoney(item.current_price)}</td><td>${item.bedrooms||'—'} BR · ${item.bathrooms||'—'} BA · ${item.square_feet?Number(item.square_feet).toLocaleString():'—'} SF</td></tr>`).join('')}</tbody></table></div><p class="csv-note">Existing listings are matched by MLS number, or by address when no MLS number is present. Blank cells will not erase existing details.</p><div class="form-actions"><button type="button" class="btn" id="backCsv">Choose another file</button><button type="button" class="btn primary" id="saveCsvListings">Import ${prepared.length} listing${prepared.length===1?'':'s'}</button></div>`;$('#backCsv').onclick=()=>openListingCsvImport();$('#saveCsvListings').onclick=()=>importListingCsv(prepared)}
async function importListingCsv(prepared){const button=$('#saveCsvListings');button.disabled=true;button.textContent='Importing…';let added=0,updated=0;try{for(const entry of prepared){const existing=matchImportedListing(entry.item);if(existing){await api('/listings/'+existing.id,{method:'PUT',body:JSON.stringify(mergeImportedListing(existing,entry.item))});updated++}else{const saved=await api('/listings',{method:'POST',body:JSON.stringify(entry.item)});state.data.listings.push(saved);added++}}closeModal();toast(`${added} listing${added===1?'':'s'} added · ${updated} updated`);await go('listings')}catch(error){button.disabled=false;button.textContent='Try import again';toast(error.message||'Import failed',true)}}
function contactFromCsv(headers,values){const row=Object.fromEntries(headers.map((header,index)=>[csvHeaderKey(header),String(values[index]||'').trim()])),read=(...names)=>names.map(name=>row[csvHeaderKey(name)]).find(Boolean)||'';let first=read('first-name','first name','firstname'),last=read('last-name','last name','lastname');const combined=read('primary_name','primary name','name');if((!first||!last)&&combined){const parts=combined.split(/\s+/).filter(Boolean);last=last||parts.pop()||'';first=first||parts.join(' ')}const phone=read('phone-mobile','mobile phone','mobile','cell phone','cell','phone-primary','phone'),email=read('primary_email','primary email','email'),street=read('address-home-street1','home street','street address'),city=read('address-home-city','home city','city'),region=read('address-home-state','home state','state'),zip=read('address-home-zip','home zip','zip'),address=[street,[city,region].filter(Boolean).join(', '),zip].filter(Boolean).join(' '),notes=address?`Home address: ${address}`:'';return {first_name:first,last_name:last,phone,email,preferred_contact:phone?'Text':'Email',source:'Other',roles:[],tags:['Flexmls Import'],notes}}
const normalizedContactPhone=value=>String(value||'').replace(/\D/g,'');
const normalizedContactText=value=>String(value||'').trim().toLowerCase();
function matchImportedContact(item,contacts=state.data.contacts||[]){const email=normalizedContactText(item.email),phone=normalizedContactPhone(item.phone),name=`${normalizedContactText(item.first_name)}|${normalizedContactText(item.last_name)}`;return contacts.find(existing=>(email&&normalizedContactText(existing.email)===email)||(phone.length>=7&&normalizedContactPhone(existing.phone)===phone)||(name!=='|'&&`${normalizedContactText(existing.first_name)}|${normalizedContactText(existing.last_name)}`===name))}
function mergeImportedContact(existing,item){const merged={...existing};for(const key of ['first_name','last_name','phone','email','preferred_contact','source'])if(!merged[key]&&item[key])merged[key]=item[key];merged.tags=[...new Set([...(existing.tags||[]),...(item.tags||[])])];if(item.notes&&!String(existing.notes||'').includes(item.notes))merged.notes=[existing.notes,item.notes].filter(Boolean).join('\n\n');return merged}
function openContactCsvImport(){$('#modalKicker').textContent='CONTACT IMPORT';$('#modalTitle').textContent='Import Flexmls contacts';$('#modalForm').innerHTML=`<div class="csv-import"><p>Choose your Flexmls contact export. You will review the matches before anything is saved.</p><label class="csv-file"><strong>Choose CSV file</strong><input id="contactCsvFile" type="file" accept=".csv,text/csv"><span id="contactCsvName">No file selected</span></label><div class="csv-help">Contacts are matched safely by email, cell phone number, or exact first and last name. Existing information will not be erased by blank CSV cells.</div><div id="contactCsvPreview"></div><div class="form-actions"><button type="button" class="btn" id="cancelContactCsv">Cancel</button><button type="button" class="btn primary" id="previewContactCsv" disabled>Preview contacts</button></div></div>`;$('#modal').classList.remove('hidden');$('#cancelContactCsv').onclick=closeModal;const input=$('#contactCsvFile'),button=$('#previewContactCsv');input.onchange=()=>{const file=input.files?.[0];$('#contactCsvName').textContent=file?.name||'No file selected';button.disabled=!file};button.onclick=()=>previewContactCsv(input)}
async function previewContactCsv(input){const file=input.files?.[0];if(!file)return;const rows=parseCsv(await file.text()),preview=$('#contactCsvPreview');if(rows.length<2){preview.innerHTML='<div class="csv-error">No contact rows were found in that CSV.</div>';return}const headers=rows[0].map(x=>x.replace(/^\uFEFF/,'')),raw=rows.slice(1).map(values=>contactFromCsv(headers,values)).filter(item=>item.first_name&&item.last_name),unique=new Map();for(const item of raw){const key=normalizedContactText(item.email)||normalizedContactPhone(item.phone)||`${normalizedContactText(item.first_name)}|${normalizedContactText(item.last_name)}`;if(!unique.has(key))unique.set(key,item)}const items=[...unique.values()];if(!items.length){preview.innerHTML='<div class="csv-error">I could not find usable first and last names in this file.</div>';return}const prepared=items.map(item=>({item,existing:matchImportedContact(item)})),updates=prepared.filter(x=>x.existing).length;preview.innerHTML=`<div class="csv-summary"><strong>${prepared.length}</strong> contact${prepared.length===1?'':'s'} ready · ${prepared.length-updates} new · ${updates} matched</div><div class="table-wrap csv-preview-table"><table><thead><tr><th>Action</th><th>Contact</th><th>Email</th><th>Cell phone</th></tr></thead><tbody>${prepared.map(({item,existing})=>`<tr><td>${badge(existing?'Update':'Add',existing?'gold':'gray')}</td><td><b>${esc(item.first_name)} ${esc(item.last_name)}</b></td><td>${esc(item.email||'—')}</td><td>${esc(item.phone||'—')}</td></tr>`).join('')}</tbody></table></div><p class="csv-note">Matched contacts keep their current CRM details; the importer fills blank fields and adds the “Flexmls Import” tag. New contacts are added without automatically placing them in the buyer or seller pipeline.</p><div class="form-actions"><button type="button" class="btn" id="backContactCsv">Choose another file</button><button type="button" class="btn primary" id="saveCsvContacts">Import ${prepared.length} contact${prepared.length===1?'':'s'}</button></div>`;$('#backContactCsv').onclick=openContactCsvImport;$('#saveCsvContacts').onclick=()=>importContactCsv(prepared)}
async function importContactCsv(prepared){const button=$('#saveCsvContacts');button.disabled=true;button.textContent='Importing…';let added=0,updated=0;try{for(const entry of prepared){const existing=matchImportedContact(entry.item);if(existing){const saved=await api('/contacts/'+existing.id,{method:'PUT',body:JSON.stringify(mergeImportedContact(existing,entry.item))});Object.assign(existing,saved);updated++}else{const saved=await api('/contacts',{method:'POST',body:JSON.stringify(entry.item)});state.data.contacts.push(saved);added++}}closeModal();toast(`${added} contact${added===1?'':'s'} added · ${updated} updated`);await go('contacts')}catch(error){button.disabled=false;button.textContent='Try import again';toast(error.message||'Import failed',true)}}
function propertyDraft(contact,listing){return {channel:'Email',subject:`A property that may fit: ${listing.address}`,body:`Hi ${contact.first_name||'there'},\n\nI have a property at ${listing.address} that may fit what you are looking for. It is listed at ${fmtMoney(listing.current_price)}${listing.bedrooms?` with ${listing.bedrooms} bedrooms`:''}.\n\nWould you like more information or to schedule a showing?\n\nEric Hepple\nParadise Property Brokers Inc`}}
async function savePropertyDraft(contact,listing){const message=propertyDraft(contact,listing);await api('/communication_drafts',{method:'POST',body:JSON.stringify({contact_id:contact.id,...message,status:'draft',source:`Property match: ${listing.address}`})});toast(`Draft created for ${contact.first_name}`)}
