 const drawOverview=()=>{$('#txPanel').innerHTML=`<div class="form-grid"><div class="field"><span>Status</span><b>${esc(record.status)}</b></div><div class="field"><span>Contract price</span><b>${fmtMoney(record.contract_price)}</b></div><div class="field"><span>Buyer</span><b>${esc(record.buyer_name||'—')}</b></div><div class="field"><span>Seller</span><b>${esc(record.seller_name||'—')}</b></div><div class="field"><span>Final Walk Through</span><b>${fmtDateTime(record.final_walkthrough_date)}</b>${calendarAction(`Final Walk Through — ${record.property}`,record.final_walkthrough_date,'Eric Hepple CRM transaction')}</div><div class="field"><span>Closing date</span><b>${fmtDateTime(record.closing_date)}</b>${calendarAction(`Closing — ${record.property}`,record.closing_date,'Eric Hepple CRM transaction')}</div><div class="field full"><span>Google Calendar notifications</span><small>After saving the event in Google Calendar, its reminders will appear on devices signed into that calendar.</small></div><div class="field full"><span>Notes</span><p>${esc(record.notes||'No transaction notes.')}</p></div><div class="form-actions"><button type="button" class="btn primary" id="editTransaction">Edit Transaction</button></div></div>`;$('#editTransaction').onclick=()=>openForm('transactions',record,record.id);};
 const drawChecklist=async()=>{const items=await api(`/transactions/${record.id}/checklist`);$('#txPanel').innerHTML=`<div class="list" style="padding:14px 26px">${items.map(item=>`<div class="list-item"><button type="button" class="icon checklist-complete" data-id="${item.id}" title="${item.status==='completed'?'Completed':'Mark complete'}">${item.status==='completed'?'●':'○'}</button><div class="grow"><p>${esc(item.title)}</p><small>${fmtDate(item.due_date)}${item.responsible_party?` · ${esc(item.responsible_party)}`:''}${item.notes?` · ${esc(item.notes)}`:''}</small></div>${badge(item.status==='completed'?'Completed':'Open',item.status==='completed'?'gray':'gold')}</div>`).join('')}</div><div class="form-grid" style="border-top:1px solid var(--line)"><label class="field"><span>New checklist item</span><input id="checkTitle" placeholder="Task or milestone"></label><label class="field"><span>Due date</span><input id="checkDue" type="date"></label><label class="field"><span>Responsible party</span><input id="checkParty" placeholder="Agent, buyer, lender…"></label><label class="field"><span>Notes</span><input id="checkNotes"></label><div class="form-actions"><button type="button" class="btn primary" id="addChecklist">Add item</button></div></div>`;$$('.checklist-complete').forEach(b=>b.onclick=async()=>{if(b.textContent==='●')return;await api('/transaction_checklist/'+b.dataset.id,{method:'PUT',body:JSON.stringify({status:'completed',completed_at:new Date().toISOString()})});toast('Checklist item completed');drawChecklist();});$('#addChecklist').onclick=async()=>{const title=$('#checkTitle').value.trim();if(!title)return toast('Enter a checklist item',true);await api(`/transactions/${record.id}/checklist`,{method:'POST',body:JSON.stringify({title,due_date:$('#checkDue').value,responsible_party:$('#checkParty').value,notes:$('#checkNotes').value})});toast('Checklist item added');drawChecklist();};};
 const drawDocuments=async()=>{const docs=await api(`/transactions/${record.id}/documents`);$('#txPanel').innerHTML=`<div class="form-grid"><label class="field full"><span>Upload document</span><input type="file" id="txFile"><small>PDF, image, Word, or other files up to 20 MB.</small></label><div class="form-actions"><button type="button" class="btn primary" id="uploadDocument">Upload</button></div><div class="field full"><span>Transaction documents</span><div class="document-list">${docs.length?docs.map(d=>`<div class="list-item"><div class="grow"><p>${esc(d.filename)}</p><small>${(d.size_bytes/1024).toFixed(1)} KB · ${fmtDate(d.created_at)}</small></div><a class="btn" href="/api/transaction-documents/${d.id}/download">Download</a><button type="button" class="btn danger delete-document" data-id="${d.id}">Remove</button></div>`).join(''):empty('No documents uploaded','Upload contracts, disclosures, inspection reports, and closing documents here.')}</div></div></div>`;$('#uploadDocument').onclick=async()=>{const file=$('#txFile').files[0];if(!file)return toast('Choose a document first',true);if(file.size>20e6)return toast('Documents must be 20 MB or smaller',true);const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});await api(`/transactions/${record.id}/documents`,{method:'POST',body:JSON.stringify({filename:file.name,mime_type:file.type,data})});toast('Document uploaded');drawDocuments();};$$('.delete-document').forEach(b=>b.onclick=async()=>{if(confirm('Remove this document from the transaction?')){await api(`/transaction-documents/${b.dataset.id}`,{method:'DELETE'});toast('Document removed');drawDocuments();}});};
