const duplicateText=value=>String(value||'').trim().toLowerCase(),duplicatePhone=value=>String(value||'').replace(/\D/g,'');
function findContactDuplicate(contact){const name=`${duplicateText(contact.first_name)} ${duplicateText(contact.last_name)}`.trim(),email=duplicateText(contact.email),phone=duplicatePhone(contact.phone);return (state.data.contacts||[]).map(existing=>{const existingName=`${duplicateText(existing.first_name)} ${duplicateText(existing.last_name)}`.trim(),reasons=[];if(name&&existingName===name)reasons.push('same first and last name');if(phone.length>=7&&duplicatePhone(existing.phone)===phone)reasons.push('same cell phone number');if(email&&duplicateText(existing.email)===email)reasons.push('same email address');return {existing,reasons}}).find(match=>match.reasons.length)}
function askDuplicateContact(match){return new Promise(resolve=>{const {existing,reasons}=match;$('#modalKicker').textContent='POSSIBLE DUPLICATE';$('#modalTitle').textContent='Is this the same contact?';$('#modalForm').innerHTML=`<div class="duplicate-warning"><p><strong>${esc(existing.first_name)} ${esc(existing.last_name)}</strong> is already in Contacts.</p><p>Matched by ${esc(reasons.join(', '))}.</p><dl><dt>CELL</dt><dd>${esc(existing.phone||'—')}</dd><dt>EMAIL</dt><dd>${esc(existing.email||'—')}</dd><dt>ROLES</dt><dd>${esc((existing.roles||[]).join(' · ')||'Contact')}</dd></dl><p><small>Choose Update Existing to add the new information and roles to this contact. Choose Create Separate only if this is a different person.</small></p><div class="form-actions"><button type="button" class="btn" id="duplicateBack">Go back</button><button type="button" class="btn" id="duplicateSeparate">Create separate</button><button type="button" class="btn primary" id="duplicateSame">Update existing</button></div></div>`;$('#duplicateBack').onclick=()=>resolve('back');$('#duplicateSeparate').onclick=()=>resolve('separate');$('#duplicateSame').onclick=()=>resolve('same')})}
async function updateExistingContact(existing,incoming){const merged={...existing};for(const [key,value]of Object.entries(incoming))if(!['roles','tags','apply_plan'].includes(key)&&value!==''&&value!==null&&value!==undefined&&value!==0)merged[key]=value;merged.roles=[...new Set([...(existing.roles||[]),...(incoming.roles||[])])];merged.tags=[...new Set([...(existing.tags||[]),...(incoming.tags||[])])];const notes=[existing.notes,incoming.notes].map(x=>String(x||'').trim()).filter(Boolean);merged.notes=[...new Set(notes)].join('\n\n');const saved=await api(`/contacts/${existing.id}`,{method:'PUT',body:JSON.stringify(merged)}),opportunities=await api('/opportunities');for(const role of merged.roles){const type=String(role).toLowerCase();if(['buyer','seller'].includes(type)&&!opportunities.some(x=>x.contact_id===existing.id&&x.type===type&&x.status!=='closed'))await api('/opportunities',{method:'POST',body:JSON.stringify({contact_id:existing.id,type,stage:'New Lead',title:`${role} opportunity`,value:0,details:{},status:'active'})})}return saved}
async function openForm(table,defaults={},editId=null){await load('contacts');if(table==='transactions'||table==='listings'||table==='tasks')await load('listings');const names={contacts:'contact',opportunities:'opportunity',listings:'listing',transactions:'transaction',tasks:'task',activities:'activity'};$('#modalKicker').textContent=editId?'EDIT RECORD':'NEW RECORD';$('#modalTitle').textContent=`${editId?'Edit':'Add'} ${names[table]}`;const fs=fields[table].filter(f=>!(editId&&f[0]==='apply_plan'));$('#modalForm').innerHTML=`<div class="form-grid">${fs.map(f=>fieldHtml(f,defaults)).join('')}<div class="form-actions">${table==='tasks'&&editId?'<button type="button" class="btn danger" id="deleteTaskModal">Delete task</button>':''}<button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">${editId?'Save changes':`Save ${names[table]}`}</button></div></div>`;$('#modal').classList.remove('hidden');$('#cancelModal').onclick=closeModal;bindDateListField();if($('#deleteTaskModal'))$('#deleteTaskModal').onclick=async()=>{if(!confirm(`Delete the task “${defaults.title||'Untitled task'}”? This cannot be undone.`))return;await api('/tasks/'+editId,{method:'DELETE'});closeModal();toast('Task deleted');go(state.view==='calendar'?'calendar':'tasks')};const type=$('[name=type]');if(type)type.onchange=updateStage;updateStage();$('#modalForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),obj={};for(const [k,v]of fd)obj[k]=v;for(const f of fs){if(f[2]==='number')obj[f[0]]=Number(obj[f[0]]||0);if(f[0]==='roles')obj.roles=fd.getAll('roles');if(f[0]==='tags')obj.tags=String(obj.tags||'').split(',').map(x=>x.trim()).filter(Boolean);if(['open_houses','price_changes','documents','deadlines','feature_highlights','gallery_urls','public_documents'].includes(f[0]))obj[f[0]]=String(obj[f[0]]||'').split('\n').map(x=>x.trim()).filter(Boolean);if(f[2]==='checkbox')obj[f[0]]=fd.has(f[0]);if(['contact_id','seller_id','co_seller_id','buyer_id','listing_id'].includes(f[0]))obj[f[0]]=obj[f[0]]?Number(obj[f[0]]):null;}try{if(table==='contacts'&&!editId){const duplicate=findContactDuplicate(obj);if(duplicate){const decision=await askDuplicateContact(duplicate);if(decision==='back')return openForm('contacts',obj);if(decision==='same'){const saved=await updateExistingContact(duplicate.existing,obj);closeModal();toast('Existing contact updated — no duplicate created');return showContact(saved.id)}}}const saved=await api('/'+table+(editId?'/'+editId:''),{method:editId?'PUT':'POST',body:JSON.stringify(obj)});closeModal();toast(editId?`${names[table][0].toUpperCase()+names[table].slice(1)} updated`:`${names[table][0].toUpperCase()+names[table].slice(1)} saved`);if(table==='listings'){await go('listings');const listing=(state.data.listings||[]).find(x=>x.id===saved.id)||saved;const count=matchingBuyers(listing).length;if(count)openListingMatches(listing)}else if(editId&&table==='contacts')showContact(editId);else if(state.contact&&table==='activities')showContact(state.contact.id);else go(state.view)}catch(err){toast(err.message,true)}};}

function openHouseValueLabel(value){const [date,start,end]=String(value||'').split('|');if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return value;const day=new Date(`${date}T12:00:00`),dateLabel=day.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'}),timeLabel=time=>{if(!time)return'';const [hour,minute]=time.split(':').map(Number);return new Date(2000,0,1,hour,minute).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})};return `${dateLabel}${start?` · ${timeLabel(start)}${end?`–${timeLabel(end)}`:''}`:''}`}
function bindDateListField(){const picker=$('.date-list-picker');if(!picker)return;const input=$('.date-list-input',picker),start=$('.date-list-start',picker),end=$('.date-list-end',picker),store=$('[name=open_houses]',picker),list=$('.date-list-values',picker),draw=()=>{const values=String(store.value||'').split('\n').map(value=>value.trim()).filter(Boolean);list.innerHTML=values.length?values.map(value=>`<button type="button" class="date-list-value" data-date="${esc(value)}"><span>${esc(openHouseValueLabel(value))}</span><b aria-label="Remove">×</b></button>`).join(''):'<small>No open houses recorded yet.</small>';$$('.date-list-value',list).forEach(button=>button.onclick=()=>{store.value=values.filter(value=>value!==button.dataset.date).join('\n');draw()})};$('.date-list-add',picker).onclick=()=>{if(!input.value||!start.value||!end.value)return toast('Choose a date, start time, and end time',true);if(end.value<=start.value)return toast('End time must be after start time',true);const value=`${input.value}|${start.value}|${end.value}`,values=String(store.value||'').split('\n').map(item=>item.trim()).filter(Boolean);if(!values.includes(value))values.push(value);store.value=values.join('\n');input.value='';start.value='';end.value='';draw()};draw()}
function fieldHtml([name,label,type,arg],defaults){const raw=defaults[name]??(name==='occurred_at'?localDateKey():name==='reminder_minutes'?60:''),value=type==='date'&&raw?String(raw).slice(0,10):type==='datetime-local'&&raw?String(raw).slice(0,16):Array.isArray(raw)?raw.join('\n'):raw;const full=['notes','body','marketing_notes','public_description','feature_highlights','gallery_urls','public_documents','open_houses','price_changes','documents','deadlines'].includes(name)?' full':'';let input='';if(type==='select'){const options=Array.isArray(arg?.[0])?arg:arg.map(x=>[x,x||'— Select —']);input=`<select name="${name}">${options.map(([option,text])=>`<option value="${esc(option)}" ${String(option)===String(value)?'selected':''}>${esc(text)}</option>`).join('')}</select>`}else if(type==='roles')input=`<div class="role-picks">${['Buyer','Seller','Agent','Past Client'].map(x=>`<label><input type="checkbox" name="roles" value="${x}" ${(Array.isArray(value)?value:[]).includes(x)?'checked':''}> ${x}</label>`).join('')}</div><small>Select Buyer or Seller to create its pipeline automatically.</small>`;else if(type==='textarea')input=`<textarea name="${name}">${esc(value)}</textarea>`;else if(type==='date-list')input=`<div class="date-list-picker"><div class="date-list-controls"><input class="date-list-input" type="date" aria-label="Choose an open-house date"><button type="button" class="btn date-list-add">Add date</button></div><textarea name="${name}" hidden>${esc(value)}</textarea><div class="date-list-values"></div><small>Choose a date from the calendar, then select Add date.</small></div>`;else if(type==='contact')input=`<select name="${name}"><option value="">— None —</option>${state.data.contacts.map(c=>`<option value="${c.id}" ${String(value||state.contact?.id||'')===String(c.id)?'selected':''}>${esc(c.first_name)} ${esc(c.last_name)}</option>`).join('')}</select>`;else if(type==='listing')input=`<select name="${name}"><option value="">— None —</option>${(state.data.listings||[]).map(x=>`<option value="${x.id}" ${String(value)===String(x.id)?'selected':''}>${esc(x.address)}</option>`).join('')}</select>`;else if(type==='stage')input=`<select name="${name}" id="stageSelect"></select>`;else if(type==='checkbox')return `<label class="field full"><span><input type="checkbox" name="${name}" checked> ${label}</span></label>`;else input=`<input name="${name}" type="${type}" value="${esc(value)}" ${arg===1?'required':''}>`;return `<label class="field${full}"><span>${label}</span>${input}</label>`}
const fieldHtmlBeforeOpenHouseTimes=fieldHtml;fieldHtml=(field,defaults)=>{const [name,label,type]=field;if(type!=='date-list')return fieldHtmlBeforeOpenHouseTimes(field,defaults);const raw=defaults[name]??'',value=Array.isArray(raw)?raw.join('\n'):raw;return `<label class="field full"><span>Open-house dates and times</span><div class="date-list-picker"><div class="date-list-controls"><div class="date-list-part"><small>Date</small><input class="date-list-input" type="date" aria-label="Open-house date"></div><div class="date-list-part"><small>Start time</small><input class="date-list-start" type="time" aria-label="Open-house start time"></div><div class="date-list-part"><small>End time</small><input class="date-list-end" type="time" aria-label="Open-house end time"></div><button type="button" class="btn date-list-add">Add open house</button></div><textarea name="${name}" hidden>${esc(value)}</textarea><div class="date-list-values"></div><small>Choose the date, start time, and end time, then select Add open house.</small></div></label>`};
function updateStage(){const s=$('#stageSelect');if(!s)return;const type=$('[name=type]')?.value||'buyer';s.innerHTML=(type==='seller'?sellerStages:buyerStages).map(x=>`<option>${x}</option>`).join('')}
function closeModal(){$('#modal').classList.add('hidden')}
const documentKinds={contact:{parent:'contacts',files:'contact-documents'},transaction:{parent:'transactions',files:'transaction-documents'},listing:{parent:'listings',files:'listing-documents'},task:{parent:'tasks',files:'task-documents'},general:{parent:'documents',files:'general-documents'}};
const documentEndpoint=(kind,id)=>kind==='general'?'/documents':`/${documentKinds[kind].parent}/${id}/documents`;
function documentRow(document,kind){return `<div class="document-entry"><div class="list-item"><div class="grow"><p>${esc(document.filename)}</p><small>${(Number(document.size_bytes||0)/1024).toFixed(1)} KB · ${fmtDate(document.created_at)}${document.category?` · ${esc(document.category)}`:''}${document.ai_summary?' · Read':''}</small></div><button type="button" class="btn read-document" data-document-kind="${kind}" data-document-id="${document.id}" data-document-name="${esc(document.filename)}">${document.ai_summary?'Read again':'Read & summarize'}</button><a class="btn" href="/api/${documentKinds[kind].files}/${document.id}/download">Download</a><button type="button" class="btn danger managed-document-delete" data-document-kind="${kind}" data-document-id="${document.id}">Remove</button></div>${document.ai_summary?`<div class="document-insight"><strong>Document summary</strong><p>${esc(document.ai_summary)}</p>${document.key_details?.length?`<ul>${document.key_details.map(detail=>`<li>${esc(detail)}</li>`).join('')}</ul>`:''}<small>Generated from this file on ${fmtDateTime(document.analyzed_at)}. Review the original before relying on dates or terms.</small></div>`:''}</div>`}
async function fileAsData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}
