function drawChronologicalContactTimeline(id){
 const contact=state.contact;if(!contact||Number(contact.id)!==Number(id))return;
 const activities=(state.data.activities||[]).filter(item=>Number(item.contact_id)===Number(id)).map(item=>({at:item.occurred_at||item.created_at||'',html:eventRow(item)}));
 const opportunities=(state.data.opportunities||[]).filter(item=>Number(item.contact_id)===Number(id)).map(item=>({at:item.updated_at||item.created_at||'',html:`<div class="event"><h4>${esc(item.type)} opportunity · ${esc(item.stage)}</h4><p>${esc(item.title||'Pipeline opportunity')} · ${fmtMoney(item.value)}</p><small>${fmtDate(item.updated_at||item.created_at)}</small></div>`}));
 const tasks=(state.data.tasks||[]).filter(item=>!item._calendar&&Number(item.contact_id)===Number(id)).map(item=>({at:item.completed_at||item.due_at||item.updated_at||item.created_at||'',html:`<div class="event"><h4>Task · ${esc(item.status)}</h4><p>${esc(item.title)}</p><small>Due ${fmtDateTime(item.due_at)}${item.completed_at?` · Completed ${fmtDateTime(item.completed_at)}`:''}</small></div>`}));
 const rows=[...activities,...opportunities,...tasks].sort((a,b)=>(Date.parse(b.at)||0)-(Date.parse(a.at)||0));
 $('#contactPanel').innerHTML=`<div class="timeline"><div class="event"><h4>Notes</h4><p>${esc(contact.notes||'No notes yet.')}</p></div>${rows.map(item=>item.html).join('')}</div>`;
}
const contactGmailSyncedThisSession=new Set();
showContact=async id=>{
 await showContactRecord(id);
 drawChronologicalContactTimeline(id);
 const timelineTab=$('[data-contact-tab="timeline"]');
 if(timelineTab)timelineTab.onclick=()=>{$$('[data-contact-tab]').forEach(tab=>tab.classList.toggle('active',tab===timelineTab));drawChronologicalContactTimeline(id)};
 const tabs=$('[data-contact-tab="timeline"]')?.parentElement;
 if(!tabs||$('[data-contact-tab="communications"]'))return;
 const button=document.createElement('button');button.className='tab';button.dataset.contactTab='communications';button.textContent='Communications';tabs.insertBefore(button,$('[data-contact-tab="documents"]'));
 button.onclick=async()=>{await load('contacts','activities','communication_drafts','tasks');$$('[data-contact-tab]').forEach(x=>x.classList.toggle('active',x===button));const contact=(state.data.contacts||[]).find(x=>Number(x.id)===Number(id)),gmailReady=Boolean(contact?.email&&window.crmGmail?.connected),communications=(state.data.activities||[]).filter(x=>Number(x.contact_id)===Number(id)&&['Call','Text','Email','Follow-up'].includes(x.type)).sort((a,b)=>String(b.occurred_at||b.created_at||'').localeCompare(String(a.occurred_at||a.created_at||''))),drafts=(state.data.communication_drafts||[]).filter(x=>Number(x.contact_id)===Number(id)),openFollowUps=(state.data.tasks||[]).filter(x=>!x._calendar&&Number(x.contact_id)===Number(id)&&x.status==='open'),last=communications[0];$('#contactPanel').innerHTML=`<div class="communication-summary"><div><small>LAST COMMUNICATION</small><strong>${last?`${esc(last.type)} · ${fmtDateTime(last.occurred_at)}`:'None logged'}</strong></div><div><small>OPEN FOLLOW-UPS</small><strong>${openFollowUps.length}</strong></div><div><small>DRAFTS WAITING</small><strong>${drafts.filter(x=>x.status==='draft').length}</strong></div></div><div class="card-head"><div><h2>Communication history</h2><small>Confirmed calls, texts, emails, and completed follow-ups.</small></div><div class="contact-communication-actions">${gmailReady?'<button class="btn" id="syncContactGmail">Sync Gmail</button>':''}<button class="btn primary" id="logContactCommunication">＋ Log communication</button></div></div><div class="timeline">${communications.length?communications.map(eventRow).join(''):empty('No communication logged','Calls, texts, emails, and completed follow-ups will appear here.')}</div><div class="communication-note">${gmailReady?`Gmail messages matching ${esc(contact.email)} are added here automatically when this tab opens. `:''}Messages opened from the CRM are recorded as initiated. Use “Mark sent & complete” after sending, or log an incoming reply manually.</div>`;$('#logContactCommunication').onclick=()=>openForm('activities',{contact_id:id,type:'Call',direction:'Outgoing'});const syncContact=async manual=>{if(!window.syncGmailContact)return;const result=await window.syncGmailContact(id,{manual});if(result?.imported){contactGmailSyncedThisSession.add(Number(id));await button.onclick()}};if($('#syncContactGmail'))$('#syncContactGmail').onclick=()=>syncContact(true);if(gmailReady&&!contactGmailSyncedThisSession.has(Number(id))){contactGmailSyncedThisSession.add(Number(id));syncContact(false)}};
};

const NOTIFICATION_PREFS_KEY='crm_notification_preferences',NOTIFICATION_DELIVERED_KEY='crm_device_notifications_delivered';
function notificationPreferences(){try{return {...{open_house_sign_in:true,task_due:true,closing_soon:true,sync_error:true},...JSON.parse(localStorage.getItem(NOTIFICATION_PREFS_KEY)||'{}')}}catch{return {open_house_sign_in:true,task_due:true,closing_soon:true,sync_error:true}}}
function notificationTaskId(item){return Number(item.task_id||String(item.source_id||'').match(/^task-(\d+)-/)?.[1]||0)}
function taskReminderAt(task){const due=new Date(task?.due_at),minutes=Number(task?.reminder_minutes||0);return !minutes||Number.isNaN(due.getTime())?null:new Date(due.getTime()-minutes*60000)}
async function openNotificationTask(taskId){await load('contacts','tasks','listings');const task=(state.data.tasks||[]).find(item=>!item._calendar&&Number(item.id)===Number(taskId));if(!task)return toast('That task is no longer available',true);openForm('tasks',task,task.id)}
async function ensureOperationalNotifications(){await load('tasks','transactions','notifications');const existing=new Set((state.data.notifications||[]).map(x=>x.source_id)),now=new Date(),today=localDateKey(now),inSeven=localDateKey(localDateAfter(7,now)),toCreate=[];for(const task of state.data.tasks||[]){if(task._calendar||task.status!=='open'||!task.due_at)continue;const reminderAt=taskReminderAt(task);if(!reminderAt||now<reminderAt)continue;const due=new Date(task.due_at),source=`task-${task.id}-${String(task.due_at).replace(/[^0-9]/g,'')}-${Number(task.reminder_minutes)}`;if(!existing.has(source))toCreate.push({type:'task_due',source_id:source,task_id:task.id,contact_id:task.contact_id||null,title:now>due?'Overdue task':'Task reminder',message:`${task.title} · ${fmtDateTime(task.due_at)}`,due_at:task.due_at,read:false})}for(const tx of state.data.transactions||[]){const day=calendarKey(tx.closing_date);if(!day||day<today||day>inSeven||tx.status==='Closed')continue;const source=`closing-${tx.id}-${day}`;if(!existing.has(source))toCreate.push({type:'closing_soon',source_id:source,title:'Closing date approaching',message:`${tx.property} · ${fmtDate(tx.closing_date)}`,read:false})}for(const item of toCreate)await api('/notifications',{method:'POST',body:JSON.stringify(item)});if(toCreate.length)await load('notifications')}
async function deliverDeviceNotifications(items){if(!('Notification'in window)||Notification.permission!=='granted')return;const prefs=notificationPreferences();let delivered={};try{delivered=JSON.parse(localStorage.getItem(NOTIFICATION_DELIVERED_KEY)||'{}')}catch{}const registration='serviceWorker'in navigator?await navigator.serviceWorker.ready.catch(()=>null):null;for(const item of items){if(item.read||item.background_delivered_at||prefs[item.type]===false||delivered[item.id]===item.created_at||item.type==='task_due'&&/^task-\d+-\d{4}-\d{2}-\d{2}$/.test(String(item.source_id||'')))continue;const taskId=notificationTaskId(item),task=taskId?(state.data.tasks||[]).find(entry=>!entry._calendar&&Number(entry.id)===taskId):null;if(item.type==='task_due'&&task){const reminderAt=taskReminderAt(task);if(!reminderAt||new Date()<reminderAt)continue}const url=new URL(location.href);if(taskId){url.searchParams.set('openTask',taskId);url.hash='tasks'}else if(item.contact_id){url.searchParams.set('openContact',item.contact_id);url.hash='contacts'}const options={body:item.message||'',icon:'./icon.svg',badge:'./icon.svg',tag:`crm-${item.id}`,data:{contact_id:item.contact_id||null,task_id:taskId||null,url:url.href}};if(registration)await registration.showNotification(item.title||'CRM notification',options);else{const alert=new Notification(item.title||'CRM notification',options);alert.onclick=()=>{window.focus();if(taskId)openNotificationTask(taskId);else if(item.contact_id)showContact(Number(item.contact_id))}}delivered[item.id]=item.created_at||true}localStorage.setItem(NOTIFICATION_DELIVERED_KEY,JSON.stringify(delivered))}
async function enableDeviceNotifications(){if(!('Notification'in window))return toast('Device alerts are not supported in this browser',true);const permission=await Notification.requestPermission();if(permission==='granted'){toast('Device alerts enabled');await refreshNotifications()}else toast('Notifications were not enabled. Check this site in device settings.',true)}
async function refreshNotifications(){
 await ensureOperationalNotifications();
 const notifications=(await api('/notifications')).sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))),unread=notifications.filter(x=>!x.read).length,badgeEl=$('#notificationBadge'),panel=$('#notificationPanel');
 badgeEl.textContent=unread>99?'99+':unread;badgeEl.hidden=!unread;
 const permission='Notification'in window?Notification.permission:'unsupported';panel.innerHTML=`<div class="panel-head"><h3>Notifications</h3>${unread?'<button class="btn" id="markNotificationsRead">Mark all read</button>':''}</div><div class="notification-device"><div><strong>Device alerts</strong><small>${permission==='granted'?'Enabled on this device':permission==='denied'?'Blocked in device settings':'Get open-house and due-date alerts outside the CRM.'}</small></div>${permission==='default'?'<button class="btn primary" id="enableDeviceNotifications">Enable</button>':''}</div>${notifications.length?notifications.slice(0,30).map(x=>`<div class="notification-entry ${x.read?'read':'unread'}" data-notification-id="${x.id}" data-contact-id="${x.contact_id||''}" data-task-id="${notificationTaskId(x)||''}"><span class="dot"></span><div><p>${esc(x.title||'CRM notification')}</p><small>${esc(x.message||'')}</small><small>${fmtDateTime(x.created_at)}</small>${x.action_phone&&x.action_body?`<a class="btn notification-action" href="sms:${phoneHref(x.action_phone)}?&body=${encodeURIComponent(x.action_body)}">${esc(x.action_label||'Send Text')}</a>`:''}</div></div>`).join(''):`<div class="empty"><strong>No notifications</strong>Open-house sign-ins and due items will appear here.</div>`}`;
 if($('#enableDeviceNotifications'))$('#enableDeviceNotifications').onclick=enableDeviceNotifications;
 $$('.notification-action',panel).forEach(link=>link.onclick=async e=>{e.stopPropagation();const entry=link.closest('.notification-entry'),id=Number(entry.dataset.notificationId);await api('/notifications/'+id,{method:'PUT',body:JSON.stringify({read:true,read_at:new Date().toISOString()})});toast('Thank-you text opened — tap Send in Messages')});
 $$('.notification-entry',panel).forEach(entry=>entry.onclick=async()=>{const id=Number(entry.dataset.notificationId),taskId=Number(entry.dataset.taskId||0);await api('/notifications/'+id,{method:'PUT',body:JSON.stringify({read:true,read_at:new Date().toISOString()})});panel.classList.add('hidden');if(taskId)await openNotificationTask(taskId);else if(entry.dataset.contactId)showContact(Number(entry.dataset.contactId));else await refreshNotifications()});
 if($('#markNotificationsRead'))$('#markNotificationsRead').onclick=async()=>{for(const item of notifications.filter(x=>!x.read))await api('/notifications/'+item.id,{method:'PUT',body:JSON.stringify({read:true,read_at:new Date().toISOString()})});await refreshNotifications()};
 await deliverDeviceNotifications(notifications);
}
