document.addEventListener('click',e=>{const action=e.target.closest('[data-comm-kind][data-contact-id]');if(!action||action.matches('[data-gmail-contact]'))return;const type=action.dataset.commKind,subject=type==='Call'?'Call initiated':type==='Text'?'Text message opened':'Email draft opened';api('/activities',{method:'POST',body:JSON.stringify({contact_id:Number(action.dataset.contactId),type,direction:'Outgoing',subject,body:'Initiated from the CRM. Add a note afterward if the conversation was completed.',occurred_at:new Date().toISOString()})}).catch(console.error)},true);
document.addEventListener('click',e=>{const n=e.target.closest('.navitem');if(n?.dataset.view)go(n.dataset.view)});$('#quickAdd').onclick=()=>openForm('contacts');$('#closeModal').onclick=closeModal;$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};$('#menuBtn').onclick=()=>$('.sidebar').classList.contains('open')?closeMenu():openMenu();$('#closeMenuBtn').onclick=closeMenu;$('#menuBackdrop').onclick=closeMenu;
async function openActionPlanPicker(contact){
 await load('action_plans');
 const roles=(contact.roles||[]).map(role=>String(role).toLowerCase()),timelineRank={hot:0,soon:1,later:2},timelineCode=value=>String(value||'').toLowerCase().startsWith('hot')?'hot':String(value||'').includes('1–3')||String(value||'').includes('1-3')?'soon':String(value||'').includes('3+')?'later':'';
 const plans=(state.data.action_plans||[]).filter(plan=>plan.active&&(['buyer','seller'].includes(String(plan.source||'').toLowerCase())?roles.includes(String(plan.source).toLowerCase()):String(plan.source||'').toLowerCase()===String(contact.source||'').toLowerCase())).sort((a,b)=>(timelineRank[a.timeline]??9)-(timelineRank[b.timeline]??9)||String(a.name).localeCompare(String(b.name)));
 if(!plans.length)return toast('No matching action plans are available for this contact',true);
 const recommended=plans.find(plan=>String(plan.source).toLowerCase()==='buyer'&&plan.timeline===timelineCode(contact.buyer_timeline))||plans.find(plan=>String(plan.source).toLowerCase()==='seller'&&plan.timeline===timelineCode(contact.seller_timeline))||plans[0];
 $('#modalKicker').textContent='FOLLOW-UP STRATEGY';$('#modalTitle').textContent='Choose an action plan';
 $('#modalForm').innerHTML=`<div class="form-grid"><label class="field full"><span>Contact</span><strong>${esc(contact.first_name)} ${esc(contact.last_name)}</strong><small>Select the cadence that matches this client’s current buying or selling timeline.</small></label><label class="field full"><span>Action plan</span><select name="plan_id">${plans.map(plan=>`<option value="${plan.id}" ${plan.id===recommended.id?'selected':''}>${esc(plan.name)} · ${plan.steps.length} steps</option>`).join('')}</select></label><div class="field full" id="planPreview"></div><div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">Create follow-ups</button></div></div>`;
 const select=$('#modalForm [name=plan_id]'),drawPreview=()=>{const plan=plans.find(item=>Number(item.id)===Number(select.value));$('#planPreview').innerHTML=`<span>Plan schedule</span><div class="list">${plan.steps.map(step=>`<div class="list-item"><div class="datebox"><b>${step.day}</b>DAY</div><div class="grow"><p>${esc(step.title)}</p></div></div>`).join('')}</div>`};select.onchange=drawPreview;drawPreview();$('#modal').classList.remove('hidden');$('#cancelModal').onclick=closeModal;
 $('#modalForm').onsubmit=async event=>{event.preventDefault();const plan=plans.find(item=>Number(item.id)===Number(select.value)),result=await api(`/contacts/${contact.id}/apply-plan`,{method:'POST',body:JSON.stringify({plan_id:plan.id})});closeModal();toast(result.created?`${plan.name}: ${result.created} follow-ups created`:'No follow-ups were created');await showContact(contact.id)};
}
const modalElement=$('#modal');new MutationObserver(()=>document.body.classList.toggle('modal-open',!modalElement.classList.contains('hidden'))).observe(modalElement,{attributes:true,attributeFilter:['class']});
document.addEventListener('focusin',event=>{if(!event.target.closest('#modalForm')||!matchMedia('(max-width:720px)').matches)return;setTimeout(()=>{if(document.activeElement===event.target)event.target.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'})},350)});

function contactNameValue(contact){return `${contact?.first_name||''} ${contact?.last_name||''}`.trim()||'Contact'}
function lastRelationshipDate(contact,activities=[]){const values=[contact.last_contact,...activities.filter(item=>Number(item.contact_id)===Number(contact.id)).map(item=>item.occurred_at||item.created_at),contact.created_at].filter(Boolean).map(value=>Date.parse(value)).filter(Number.isFinite);return values.length?new Date(Math.max(...values)):null}
function sourcePerformanceRows(){const contacts=state.data.contacts||[],opportunities=state.data.opportunities||[],transactions=state.data.transactions||[],groups=new Map();for(const contact of contacts){const source=String(contact.source||'Unknown').trim()||'Unknown';if(!groups.has(source))groups.set(source,{source,leads:0,active:0,closed:new Set(),volume:0,commission:0});const group=groups.get(source);group.leads++;if(opportunities.some(item=>Number(item.contact_id)===Number(contact.id)&&item.status!=='closed'&&!['Closed','Nurture/Lost'].includes(item.stage)))group.active++}for(const transaction of transactions.filter(item=>String(item.status).toLowerCase()==='closed')){const ids=[transaction.buyer_id,transaction.seller_id,transaction.co_seller_id].map(Number).filter(Boolean),sources=new Set(ids.map(id=>contacts.find(contact=>Number(contact.id)===id)?.source||'Unknown'));for(const source of sources){if(!groups.has(source))groups.set(source,{source,leads:0,active:0,closed:new Set(),volume:0,commission:0});const group=groups.get(source);ids.filter(id=>(contacts.find(contact=>Number(contact.id)===id)?.source||'Unknown')===source).forEach(id=>group.closed.add(id));group.volume+=Number(transaction.contract_price||0);group.commission+=Number(transaction.commission||0)}}return [...groups.values()].map(group=>({...group,closedCount:group.closed.size,conversion:group.leads?Math.round(group.closed.size/group.leads*100):0})).sort((a,b)=>b.closedCount-a.closedCount||b.active-a.active||b.leads-a.leads)}
function sourcePerformanceHtml(){const rows=sourcePerformanceRows();return `<section class="card intelligence-section" id="sourcePerformance"><div class="card-head"><div><h2>Lead source performance</h2><small>Conversion and closed revenue attributed to the source on each contact. True ROI will be available when marketing spend is recorded.</small></div></div><div class="table-wrap"><table><thead><tr><th>Source</th><th>Leads</th><th>Active</th><th>Closed</th><th>Conversion</th><th>Closed volume</th><th>Commission</th></tr></thead><tbody>${rows.map(row=>`<tr><td><strong>${esc(row.source)}</strong></td><td>${row.leads}</td><td>${row.active}</td><td>${row.closedCount}</td><td>${row.conversion}%</td><td>${fmtMoney(row.volume)}</td><td>${fmtMoney(row.commission)}</td></tr>`).join('')||'<tr><td colspan="7">No lead-source data yet.</td></tr>'}</tbody></table></div></section>`}

function databaseHealthModel(){const contacts=state.data.contacts||[],activities=state.data.activities||[],tasks=(state.data.tasks||[]).filter(item=>!item._calendar),opportunities=(state.data.opportunities||[]).filter(item=>item.status!=='closed'&&!['Closed','Nurture/Lost'].includes(item.stage)),today=new Date(),activeIds=new Set(opportunities.map(item=>Number(item.contact_id))),issues=[];for(const contact of contacts){const last=lastRelationshipDate(contact,activities),days=last?Math.max(0,Math.floor((today-last)/864e5)):9999,active=activeIds.has(Number(contact.id)),missing=[];if(!String(contact.phone||'').trim())missing.push('phone');if(!String(contact.email||'').trim())missing.push('email');if(active&&!contact.next_follow_up)issues.push({contact,type:'No follow-up',severity:4,detail:'Active opportunity without a scheduled next step.'});if(days>=90)issues.push({contact,type:'Re-engage',severity:3,detail:`No recorded contact in ${days===9999?'90+':days} days.`});else if(days>=30)issues.push({contact,type:'Dormant',severity:2,detail:`No recorded contact in ${days} days.`});else if(days>=14&&active)issues.push({contact,type:'Stale',severity:2,detail:`Active relationship untouched for ${days} days.`});if(missing.length)issues.push({contact,type:'Missing information',severity:1,detail:`Missing ${missing.join(' and ')}.`})}const overdue=tasks.filter(task=>task.status==='open'&&task.due_at&&new Date(task.due_at)<today),duplicates=[];const seen=new Map();for(const contact of contacts){for(const key of [String(contact.email||'').trim().toLowerCase(),String(contact.phone||'').replace(/\D/g,'')].filter(value=>value.length>=7)){if(seen.has(key)&&seen.get(key)!==contact.id)duplicates.push(contact);else seen.set(key,contact.id)}}const uniqueAffected=new Set(issues.map(issue=>issue.contact.id)),score=Math.max(0,100-Math.min(70,uniqueAffected.size*2)-Math.min(20,overdue.length*2)-Math.min(10,duplicates.length*3));return {score,issues:issues.sort((a,b)=>b.severity-a.severity||contactNameValue(a.contact).localeCompare(contactNameValue(b.contact))),overdue,duplicates:[...new Map(duplicates.map(contact=>[contact.id,contact])).values()]}}
function reengagementMessage(contact){const first=contact.first_name||'there',roles=(contact.roles||[]).map(role=>String(role).toLowerCase()),subject=roles.includes('seller')?'Checking in on your real-estate plans':roles.includes('buyer')?'Checking in on your home search':'Checking in',body=roles.includes('seller')?`Hi ${first},\n\nI wanted to check in and see whether your timing or plans for selling have changed. I would be happy to share an updated market perspective and help you think through the next step when the time is right.\n\nEric Hepple\nParadise Property Brokers Inc`:roles.includes('buyer')?`Hi ${first},\n\nI wanted to check in and see how your home search is going. Have your timing, preferred areas, or must-have features changed? I would be happy to update the search and help with the next step.\n\nEric Hepple\nParadise Property Brokers Inc`:`Hi ${first},\n\nI wanted to check in and see how you are doing. If you have any real-estate questions or plans I can help with, I would be glad to be a resource.\n\nEric Hepple\nParadise Property Brokers Inc`;return {subject,body}}
async function openReengagementDraft(contact){const draft=reengagementMessage(contact);$('#modalKicker').textContent='RE-ENGAGEMENT';$('#modalTitle').textContent=`Prepare message for ${contactNameValue(contact)}`;$('#modalForm').innerHTML=`<div class="form-grid"><label class="field"><span>Type</span><select name="channel"><option>Email</option><option>Text</option></select></label><label class="field full"><span>Subject</span><input name="subject" value="${esc(draft.subject)}"></label><label class="field full"><span>Message</span><textarea name="body">${esc(draft.body)}</textarea></label><div class="field full"><small>Nothing is sent automatically. This saves a draft for your review.</small></div><div class="form-actions"><button type="button" class="btn" id="cancelReengagement">Cancel</button><button class="btn primary">Save draft for review</button></div></div>`;$('#modal').classList.remove('hidden');$('#cancelReengagement').onclick=closeModal;$('#modalForm').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);await api('/communication_drafts',{method:'POST',body:JSON.stringify({contact_id:contact.id,channel:form.get('channel'),subject:form.get('subject'),body:form.get('body'),status:'draft',source:'Database health re-engagement'})});closeModal();toast('Re-engagement draft saved for review');go('inbox')}}
function healthIssueRow(issue){const action=issue.type==='No follow-up'?`<button class="btn primary" data-health-task="${issue.contact.id}">Schedule next step</button>`:issue.type==='Missing information'?`<button class="btn primary" data-health-edit-contact="${issue.contact.id}">Add details</button>`:`<button class="btn primary" data-health-draft="${issue.contact.id}">Prepare message</button>`;return `<div class="list-item health-row"><div class="grow"><p>${esc(contactNameValue(issue.contact))} ${badge(issue.type,issue.severity>=3?'gold':'gray')}</p><small>${esc(issue.detail)}</small></div><div class="health-actions"><button class="btn" data-health-contact="${issue.contact.id}">Open contact</button>${action}</div></div>`}
function healthTaskRow(task){const contact=(state.data.contacts||[]).find(item=>Number(item.id)===Number(task.contact_id));return `<div class="list-item health-row"><div class="grow"><p>${esc(task.title||'Task')} ${badge('Overdue','red')}</p><small>${contact?`${esc(contactNameValue(contact))} · `:''}Due ${fmtDateTime(task.due_at)}</small></div><div class="health-actions"><button class="btn" data-health-edit-task="${task.id}">Open task</button><button class="btn primary" data-health-complete-task="${task.id}">Mark complete</button></div></div>`}
function healthDuplicateRow(contact){const email=String(contact.email||'').trim(),phone=String(contact.phone||'').trim();return `<div class="list-item health-row"><div class="grow"><p>${esc(contactNameValue(contact))} ${badge('Possible duplicate','gold')}</p><small>${esc([email,phone].filter(Boolean).join(' · ')||'Matching contact information found')}</small></div><div class="health-actions"><button class="btn primary" data-health-contact="${contact.id}">Review contact</button></div></div>`}
function healthReviewModel(health,filter){const issueGroups={all:health.issues,'no-follow':health.issues.filter(issue=>issue.type==='No follow-up'),reengage:health.issues.filter(issue=>['Re-engage','Dormant','Stale'].includes(issue.type)),missing:health.issues.filter(issue=>issue.type==='Missing information')};if(filter==='overdue')return {title:'Overdue tasks',help:'Open the exact task or mark it complete without leaving Database Health.',html:health.overdue.length?health.overdue.sort((a,b)=>String(a.due_at||'').localeCompare(String(b.due_at||''))).map(healthTaskRow).join(''):empty('No overdue tasks','Your open tasks are currently on schedule.')};if(filter==='duplicates')return {title:'Possible duplicates',help:'Review each contact before deciding whether records should be combined.',html:health.duplicates.length?health.duplicates.map(healthDuplicateRow).join(''):empty('No possible duplicates','No matching phone numbers or email addresses were found.')};const issues=issueGroups[filter]||health.issues,titles={all:'Priority cleanup and re-engagement','no-follow':'Active relationships with no next step',reengage:'Contacts ready for re-engagement',missing:'Contacts with missing details'},helps={all:'Highest-impact items appear first. Drafts open for review and are never sent automatically.','no-follow':'Open the contact or schedule the next follow-up directly.','reengage':'Open the contact or prepare a message for review. Nothing is sent automatically.',missing:'Open the contact to add the missing phone number or email address.'};return {title:titles[filter]||titles.all,help:helps[filter]||helps.all,html:issues.length?issues.slice(0,100).map(healthIssueRow).join(''):empty(filter==='all'?'Database looks healthy':'Nothing needs review','No records currently match this category.')}}
function bindHealthActions(){$$('[data-health-filter]').forEach(button=>button.onclick=()=>{state.healthFilter=button.dataset.healthFilter;views.health()});$$('[data-health-contact]').forEach(button=>button.onclick=()=>showContact(Number(button.dataset.healthContact)));$$('[data-health-edit-contact]').forEach(button=>button.onclick=()=>{const contact=(state.data.contacts||[]).find(item=>Number(item.id)===Number(button.dataset.healthEditContact));if(contact)openForm('contacts',contact,contact.id)});$$('[data-health-task]').forEach(button=>button.onclick=()=>{const contact=state.data.contacts.find(item=>Number(item.id)===Number(button.dataset.healthTask));openForm('tasks',{contact_id:contact.id,title:'Personal follow-up',due_at:localDateTimeValue(localDateAfter(1)),priority:'Medium',notes:`Database health follow-up for ${contactNameValue(contact)}`})});$$('[data-health-draft]').forEach(button=>button.onclick=()=>{const contact=state.data.contacts.find(item=>Number(item.id)===Number(button.dataset.healthDraft));openReengagementDraft(contact)});$$('[data-health-edit-task]').forEach(button=>button.onclick=()=>{const task=(state.data.tasks||[]).find(item=>!item._calendar&&Number(item.id)===Number(button.dataset.healthEditTask));if(task)openForm('tasks',task,task.id)});$$('[data-health-complete-task]').forEach(button=>button.onclick=async()=>{button.disabled=true;await api('/tasks/'+button.dataset.healthCompleteTask,{method:'PUT',body:JSON.stringify({status:'completed',completed_at:new Date().toISOString()})});await load('tasks');toast('Task completed');views.health()})}
views.health=async()=>{await load('contacts','activities','tasks','opportunities','communication_drafts');const health=databaseHealthModel(),reengage=health.issues.filter(issue=>['Re-engage','Dormant','Stale'].includes(issue.type)),noFollow=health.issues.filter(issue=>issue.type==='No follow-up'),missing=health.issues.filter(issue=>issue.type==='Missing information'),filter=state.healthFilter||'all',review=healthReviewModel(health,filter),metric=(key,label,value,caption,attention=false)=>`<button type="button" class="metric health-metric ${attention?'attention ':''}${filter===key?'active':''}" data-health-filter="${key}" aria-pressed="${filter===key}"><span class="label">${label}</span><strong>${value}</strong><small>${caption}</small><span class="metric-arrow" aria-hidden="true">→</span></button>`;$('#app').innerHTML=header('RELATIONSHIP INTELLIGENCE','Database Health','Find missing follow-ups, stale relationships, incomplete records, duplicates, and people ready for re-engagement.',`<button class="btn primary" data-view="contacts">Open contacts</button>`)+`<section class="metrics health-metrics" aria-label="Database health filters">${metric('all','Health score',health.score,'Out of 100',health.score<75)}${metric('no-follow','No next step',noFollow.length,'Active relationships',noFollow.length>0)}${metric('reengage','Re-engage',reengage.length,'14+ days quiet')}${metric('missing','Missing details',missing.length,'Phone or email')}${metric('overdue','Overdue tasks',health.overdue.length,'Needs action',health.overdue.length>0)}${metric('duplicates','Possible duplicates',health.duplicates.length,'Review records')}</section><section class="card health-list"><div class="card-head"><div><h2>${esc(review.title)}</h2><small>${esc(review.help)}</small></div><button type="button" class="btn" data-health-filter="all" ${filter==='all'?'hidden':''}>Show all</button></div><div class="list">${review.html}</div></section>`;bind();bindHealthActions()};

