function contractDateValue(value){const text=String(value||'').trim(),numeric=text.match(/\b(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})\b/),named=text.match(/\b(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2})(?:st|nd|rd|th)?\s*,?\s*(\d{4})\b/i);let month,day,year;if(numeric){month=Number(numeric[1]);day=Number(numeric[2]);year=Number(numeric[3]);if(year<100)year+=2000}else if(named){month=['january','february','march','april','may','june','july','august','september','october','november','december'].indexOf(named[1].toLowerCase())+1;day=Number(named[2]);year=Number(named[3])}else return'';if(month<1||month>12||day<1||day>31)return'';return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
