const databaseHealthModelBeforeRecentContact=databaseHealthModel;
databaseHealthModel=()=>{const model=databaseHealthModelBeforeRecentContact(),cutoff=Date.now()-7*864e5,recentIds=new Set((state.data.activities||[]).filter(activity=>Date.parse(activity.occurred_at||activity.created_at||0)>=cutoff).map(activity=>Number(activity.contact_id)));model.issues=model.issues.filter(issue=>!(issue.type==='No follow-up'&&recentIds.has(Number(issue.contact.id))));const affected=new Set(model.issues.map(issue=>issue.contact.id));model.score=Math.max(0,100-Math.min(70,affected.size*2)-Math.min(20,model.overdue.length*2)-Math.min(10,model.duplicates.length*3));return model};

// Client Follow-Up Engine: one coordinated loop for prioritization, nurture,
// change detection, reviewed next steps, and record-specific alerts.
function followUpCadenceDays(contact){
 const text=`${contact.buyer_timeline||''} ${contact.seller_timeline||''}`.toLowerCase(),roles=(contact.roles||[]).map(role=>String(role).toLowerCase());
 if(contact.follow_up_mode==='Paused')return null;
 if(text.includes('hot'))return 2;
 if(text.includes('1–3')||text.includes('1-3'))return 7;
 if(text.includes('3+'))return 30;
 if(roles.includes('past client'))return 90;
 const opportunity=(state.data.opportunities||[]).find(item=>Number(item.contact_id)===Number(contact.id)&&item.status!=='closed'&&!['Closed','Nurture/Lost'].includes(item.stage));
 if(opportunity&&['Under Contract','Offer Submitted','Showing Homes','Listing Signed','Active Listing','Appointment Set','Listing Appointment'].includes(opportunity.stage))return 3;
 return opportunity?7:30;
}
function followUpIsAutomatic(contact){return contact.follow_up_mode==='Automatic'||(!contact.follow_up_mode&&Boolean(contact.behavior_plan_id||contact.buyer_timeline||contact.seller_timeline))}
function contactOpenTasks(contactId){return (state.data.tasks||[]).filter(task=>!task._calendar&&task.status==='open'&&Number(task.contact_id)===Number(contactId))}
function nextFollowUpRecommendation(contact){
 const cadence=followUpCadenceDays(contact)||30,roles=(contact.roles||[]).map(String),opportunity=(state.data.opportunities||[]).find(item=>Number(item.contact_id)===Number(contact.id)&&item.status!=='closed'),transaction=(state.data.transactions||[]).find(item=>item.status!=='Closed'&&[item.buyer_id,item.seller_id,item.co_seller_id].some(id=>Number(id)===Number(contact.id))),base=contact.last_contact||new Date().toISOString(),due=localDateAfter(cadence,new Date(base));
 if(due<new Date())due.setTime(Date.now()+30*60000);else due.setHours(9,0,0,0);
 const role=roles.includes('Seller')?'seller':roles.includes('Buyer')?'buyer':'client',title=transaction?`Check in about ${transaction.property}`:opportunity?.stage==='Showing Homes'?'Review showings and next homes':opportunity?.stage==='Offer Submitted'?'Review offer status and next move':`Follow up with ${contact.first_name||'client'}`;
 return {title,due_at:localDateTimeValue(due),cadence,reason:transaction?'Active transaction':opportunity?`${opportunity.type} pipeline · ${opportunity.stage}`:`${role[0].toUpperCase()+role.slice(1)} nurture · every ${cadence} days`};
}
function priorityContactsModel(limit=7){
 const today=localDateKey(),now=Date.now(),openNotifications=(state.data.notifications||[]).filter(item=>!item.read),rows=(state.data.contacts||[]).map(contact=>{const tasks=contactOpenTasks(contact.id),overdue=tasks.filter(task=>calendarKey(task.due_at)<today),due=tasks.filter(task=>calendarKey(task.due_at)===today),cadence=followUpCadenceDays(contact),last=Date.parse(contact.last_contact||contact.created_at||0),daysSince=last?Math.floor((now-last)/864e5):999,opportunity=(state.data.opportunities||[]).find(item=>Number(item.contact_id)===Number(contact.id)&&item.status!=='closed'&&!['Closed','Nurture/Lost'].includes(item.stage)),transaction=(state.data.transactions||[]).find(item=>item.status!=='Closed'&&[item.buyer_id,item.seller_id,item.co_seller_id].some(id=>Number(id)===Number(contact.id))),signals=openNotifications.filter(item=>Number(item.contact_id)===Number(contact.id)&&['client_change','next_step_missing','nurture_due'].includes(item.type));let score=0;const reasons=[];if(overdue.length){score+=55+Math.min(15,overdue.length*5);reasons.push(`${overdue.length} overdue task${overdue.length===1?'':'s'}`)}if(due.length){score+=35;reasons.push(`${due.length} due today`)}if(contact.next_follow_up&&calendarKey(contact.next_follow_up)<=today){score+=40;reasons.push('follow-up due')}if(!contact.next_follow_up&&!tasks.length&&(opportunity||contact.behavior_plan_id)){score+=25;reasons.push('no next step scheduled')}if(cadence&&daysSince>=cadence){score+=Math.min(35,15+daysSince-cadence);reasons.push(`${daysSince===999?'No':daysSince+' days since'} contact`)}if(transaction){score+=25;reasons.push('active transaction')}if(/hot/i.test(`${contact.buyer_timeline||''} ${contact.seller_timeline||''}`)){score+=20;reasons.push('hot timeline')}if(signals.length){score+=15;reasons.push('client change detected')}return {contact,score,reasons,tasks,recommendation:nextFollowUpRecommendation(contact)}}).filter(row=>row.score>0).sort((a,b)=>b.score-a.score||String(a.contact.last_name||'').localeCompare(String(b.contact.last_name||'')));return rows.slice(0,limit)
}
async function createFollowUpNotification(item){
 const notifications=state.data.notifications||[];if(notifications.some(existing=>existing.source_id===item.source_id))return null;
 const created=await api('/notifications',{method:'POST',body:JSON.stringify({...item,read:false,due_at:item.due_at||new Date().toISOString()})});notifications.push(created);return created;
}
async function ensureClientFollowUpSystem(){
 await load('contacts','tasks','opportunities','transactions','activities','notifications');const today=localDateKey(),now=new Date();
 for(const contact of state.data.contacts||[]){
  if(contact.follow_up_mode==='Paused')continue;
  let openTasks=contactOpenTasks(contact.id),recommendation=nextFollowUpRecommendation(contact),dueDay=calendarKey(recommendation.due_at),lastDay=calendarKey(contact.last_contact||contact.created_at)||today;
  if(followUpIsAutomatic(contact)&&!openTasks.length&&!contact.next_follow_up&&dueDay<=today){
   const task=await api('/tasks',{method:'POST',body:JSON.stringify({title:recommendation.title,contact_id:contact.id,due_at:recommendation.due_at,priority:/hot|transaction/i.test(`${contact.buyer_timeline||''} ${contact.seller_timeline||''} ${recommendation.reason}`)?'High':'Medium',reminder_minutes:60,status:'open',automation_key:`nurture-${contact.id}-${dueDay}`,notes:`Automatic nurture · ${recommendation.reason}. Review the contact before reaching out.`})});
   openTasks=[task];await api('/contacts/'+contact.id,{method:'PUT',body:JSON.stringify({next_follow_up:dueDay})});
  }
  const activeOpportunity=(state.data.opportunities||[]).find(item=>Number(item.contact_id)===Number(contact.id)&&item.status!=='closed'&&!['New Lead','Closed','Nurture/Lost'].includes(item.stage)),recentActivity=(state.data.activities||[]).some(item=>Number(item.contact_id)===Number(contact.id)&&Date.parse(item.occurred_at||item.created_at||0)>=Date.now()-30*864e5),needsEnforcement=Boolean(contact.behavior_plan_id||contact.buyer_timeline||contact.seller_timeline||activeOpportunity||recentActivity);
  if(needsEnforcement&&!openTasks.length&&!contact.next_follow_up){await createFollowUpNotification({type:'next_step_missing',source_id:`next-step-${contact.id}-${lastDay}`,contact_id:contact.id,title:`Next step needed · ${contact.first_name||'Contact'}`,message:`No future follow-up is scheduled. Suggested: ${recommendation.title}.`,due_at:now.toISOString()})}
  const cadence=followUpCadenceDays(contact),last=Date.parse(contact.last_contact||contact.created_at||0);if(needsEnforcement&&cadence&&last&&Date.now()-last>=cadence*864e5)await createFollowUpNotification({type:'nurture_due',source_id:`nurture-due-${contact.id}-${localDateKey(new Date(last+cadence*864e5))}`,contact_id:contact.id,title:`Nurture due · ${contact.first_name||'Contact'}`,message:`${recommendation.reason}. Open the contact to review the next move.`,due_at:now.toISOString()});
 }
 await load('contacts','tasks','notifications');
}
async function openNextStepReview(contactId,context='recent activity'){
 await load('contacts','tasks','opportunities','transactions');const contact=(state.data.contacts||[]).find(item=>Number(item.id)===Number(contactId));if(!contact||contact.follow_up_mode==='Paused')return;
 const recommendation=nextFollowUpRecommendation(contact),existing=contactOpenTasks(contact.id).sort((a,b)=>String(a.due_at||'').localeCompare(String(b.due_at||'')))[0];
 $('#modalKicker').textContent='CLIENT FOLLOW-UP ENGINE';$('#modalTitle').textContent=`Choose the next step for ${contact.first_name||'this contact'}`;$('#modalForm').innerHTML=`<div class="form-grid next-step-review"><div class="field full assistant-pending-review"><strong>${existing?'A next step is already scheduled':'Keep the relationship moving'}</strong><p>${existing?`${esc(existing.title)} · ${fmtDateTime(existing.due_at)}`:`The ${esc(context)} is recorded. Review the recommended next action before saving it.`}</p><small>${esc(recommendation.reason)}</small></div><label class="field full"><span>Next action</span><input id="nextStepTitle" value="${esc(existing?.title||recommendation.title)}"></label><label class="field"><span>Date and time</span><input id="nextStepDue" type="datetime-local" value="${esc(String(existing?.due_at||recommendation.due_at).slice(0,16))}"></label><label class="field"><span>Ongoing cadence</span><select id="nextStepMode"><option ${contact.follow_up_mode!=='Review each time'&&contact.follow_up_mode!=='Paused'?'selected':''}>Automatic</option><option ${contact.follow_up_mode==='Review each time'?'selected':''}>Review each time</option><option>Paused</option></select></label><div class="form-actions"><button type="button" class="btn" id="nextStepLater">Not now</button>${existing?'<button type="button" class="btn" id="keepNextStep">Keep current</button>':''}<button type="button" class="btn primary" id="saveNextStep">${existing?'Update next step':'Schedule next step'}</button></div></div>`;$('#modal').classList.remove('hidden');document.body.classList.add('modal-open');
 $('#nextStepLater').onclick=async()=>{await createFollowUpNotification({type:'next_step_missing',source_id:`next-step-review-${contact.id}-${localDateKey()}`,contact_id:contact.id,title:`Next step still needed · ${contact.first_name||'Contact'}`,message:'A recent interaction was logged without confirming the next action.',due_at:new Date().toISOString()});closeModal();toast('Reminder kept in Notifications')};if($('#keepNextStep'))$('#keepNextStep').onclick=closeModal;
 $('#saveNextStep').onclick=async()=>{const title=$('#nextStepTitle').value.trim(),dueAt=$('#nextStepDue').value,mode=$('#nextStepMode').value;if(mode==='Paused'){await api('/contacts/'+contact.id,{method:'PUT',body:JSON.stringify({follow_up_mode:'Paused',next_follow_up:null})});closeModal();return toast('Automatic nurture paused')}if(!title||!dueAt)return toast('Add the next action and date',true);if(existing)await api('/tasks/'+existing.id,{method:'PUT',body:JSON.stringify({title,due_at:dueAt,reminder_minutes:Number(existing.reminder_minutes||60)})});else await api('/tasks',{method:'POST',body:JSON.stringify({title,contact_id:contact.id,due_at:dueAt,priority:'Medium',reminder_minutes:60,status:'open',notes:`Next step after ${context}.`})});await api('/contacts/'+contact.id,{method:'PUT',body:JSON.stringify({next_follow_up:calendarKey(dueAt),follow_up_mode:mode})});closeModal();toast('Next step scheduled')};
}
function queueNextStepReview(contactId,context){setTimeout(()=>{if($('#modal')&&!$('#modal').classList.contains('hidden'))return setTimeout(()=>openNextStepReview(contactId,context),350);openNextStepReview(contactId,context)},80)}
function bindPriorityContactActions(root=document){$$('[data-priority-contact]',root).forEach(button=>button.onclick=()=>showContact(Number(button.dataset.priorityContact)));$$('[data-priority-next]',root).forEach(button=>button.onclick=()=>openNextStepReview(Number(button.dataset.priorityNext),'daily priority list'))}
function priorityContactSection(){const rows=priorityContactsModel();return `<section class="card follow-up-command"><div class="card-head"><div><h2>Today’s client follow-up list</h2><small>Ranked by urgency, relationship stage, overdue work, and recent changes.</small></div><button class="btn" data-view="smartlists">View smart lists</button></div>${rows.length?`<div class="priority-contact-grid">${rows.map(({contact,score,reasons,recommendation,tasks})=>{const next=[...tasks].sort((a,b)=>String(a.due_at||'').localeCompare(String(b.due_at||'')))[0]||recommendation;return `<article class="priority-contact"><div class="priority-score">${score}</div><div class="grow"><h3>${esc(contact.first_name)} ${esc(contact.last_name)}</h3><p>${esc(reasons.slice(0,3).join(' · '))}</p><small>${tasks.length?'Next':'Suggested'}: ${esc(next.title)} · ${fmtDateTime(next.due_at)}</small></div><div class="priority-actions"><button class="btn" data-priority-contact="${contact.id}">Open</button><button class="btn primary" data-priority-next="${contact.id}">Set next step</button></div></article>`}).join('')}</div>`:empty('Client follow-ups are covered','Every priority relationship has a current next step.')}</section>`}
const dashboardBeforeFollowUpEngine=views.dashboard;views.dashboard=async()=>{await dashboardBeforeFollowUpEngine();await load('contacts','tasks','opportunities','transactions','activities','notifications');const metrics=$('.metrics');if(metrics){metrics.insertAdjacentHTML('afterend',priorityContactSection());bind();bindPriorityContactActions()}};
const ensureOperationalNotificationsBeforeFollowUpEngine=ensureOperationalNotifications;ensureOperationalNotifications=async()=>{await ensureOperationalNotificationsBeforeFollowUpEngine();await ensureClientFollowUpSystem()};
let pendingListingTransactionReviewId=null;
const apiBeforePendingListingReview=api;
api=async(path,options={})=>{const match=String(path).match(/^\/listings\/(\d+)$/),contactMatch=String(path).match(/^\/contacts\/(\d+)$/),taskMatch=String(path).match(/^\/tasks\/(\d+)$/),method=String(options.method||'GET').toUpperCase(),payload=JSON.parse(options.body||'{}'),before=match&&method==='PUT'?(state.data.listings||[]).find(item=>Number(item.id)===Number(match[1])):null,contactBefore=contactMatch&&method==='PUT'?(state.data.contacts||[]).find(item=>Number(item.id)===Number(contactMatch[1])):null,taskBefore=taskMatch&&method==='PUT'?(state.data.tasks||[]).find(item=>!item._calendar&&Number(item.id)===Number(taskMatch[1])):null,activityContact=path==='/activities'&&method==='POST'?(state.data.contacts||[]).find(contact=>Number(contact.id)===Number(payload.contact_id)):null,result=await apiBeforePendingListingReview(path,options);if(match&&method==='PUT'&&String(before?.status||'').toLowerCase()!=='pending'&&String(result?.status||'').toLowerCase()==='pending')pendingListingTransactionReviewId=Number(result.id);if(activityContact&&result){const loggedAt=result.occurred_at||result.created_at||new Date().toISOString(),completedDueFollowUp=activityContact.next_follow_up&&String(activityContact.next_follow_up).slice(0,10)<=String(loggedAt).slice(0,10),update={last_contact:loggedAt};if(completedDueFollowUp)update.next_follow_up=null;await apiBeforePendingListingReview(`/contacts/${activityContact.id}`,{method:'PUT',body:JSON.stringify(update)});if(['Call','Text','Email','Follow-up','Showing','Appointment'].includes(result.type))queueNextStepReview(activityContact.id,`${String(result.type||'communication').toLowerCase()} logged`)}if(taskBefore&&taskBefore.status!=='completed'&&result?.status==='completed'&&taskBefore.contact_id)queueNextStepReview(taskBefore.contact_id,`completed task “${taskBefore.title}”`);if(contactBefore&&result){const changed=['buyer_timeline','seller_timeline','budget_min','budget_max','area','subdivision','roles'].filter(key=>JSON.stringify(contactBefore[key]||'')!==JSON.stringify(result[key]||''));if(changed.length){const notifications=await apiBeforePendingListingReview('/notifications');const source=`client-change-${result.id}-${changed.join('-')}-${String(result.updated_at||Date.now()).replace(/[^0-9]/g,'').slice(0,14)}`;if(!notifications.some(item=>item.source_id===source))await apiBeforePendingListingReview('/notifications',{method:'POST',body:JSON.stringify({type:'client_change',source_id:source,contact_id:result.id,title:`Client plan changed · ${result.first_name||'Contact'}`,message:`Updated ${changed.map(key=>key.replaceAll('_',' ')).join(', ')}. Review the next action and matching strategy.`,due_at:new Date().toISOString(),read:false})})}}return result};
async function openPendingListingTransactionReview(listingId){await load('transactions','listings','contacts');const listing=(state.data.listings||[]).find(item=>Number(item.id)===Number(listingId)),transaction=(state.data.transactions||[]).find(item=>Number(item.listing_id)===Number(listingId));if(!listing||!transaction)return toast('The pending transaction could not be opened',true);await openForm('transactions',transaction,transaction.id);$('#modalKicker').textContent='ASSISTANT · PENDING LISTING';$('#modalTitle').textContent='Complete the pending transaction';const grid=$('#modalForm .form-grid');grid?.insertAdjacentHTML('afterbegin',`<div class="field full assistant-pending-review"><strong>${esc(listing.address)} is now Pending.</strong><p>Please add the contract and closing details so deadlines, reminders, the transaction checklist, and seller pipeline stay accurate.</p><small>Confirm the transaction status, closing date, parties, price, contingency, earnest money, and important deadlines. Nothing else is sent automatically.</small></div>`)}
